                sumsq_buf,
                counter_buf,
                mean_buf,
                rstd_buf,
                f32(self.eps),
            ],
            shared_memory=0,
            stream=stream,
        )
        module.launch(
            "layernorm_apply_kernel",
            grid=(batch_size, chunks, 1),
            block=(1024, 1, 1),
            arguments=[
                x,
                self.weight,
                self.bias,
                out,
                i32(N),
                i32(chunk_size),
                mean_buf,
                rstd_buf,
            ],
            shared_memory=0,
            stream=stream,
        )
        return out
